from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option_symbol = self.AddOption("SPY", Resolution.Minute).Symbol
        self.Securities[self.option_symbol].SetFilter(
            -100, 100, timedelta(days=0), timedelta(days=365)
        )

        self.closes = RollingWindow[float](20)
        self.pending_crossover_bar_end = None

        self.held_symbol = None
        self.held_expiry = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.no_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        # The window contains completed bars ending with the preceding bar here.
        if self.closes.Count >= 20:
            previous_fast = sum(self.closes[i] for i in range(5)) / 5.0
            previous_slow = sum(self.closes[i] for i in range(20)) / 20.0

            self.closes.Add(float(bar.Close))

            current_fast = sum(self.closes[i] for i in range(5)) / 5.0
            current_slow = sum(self.closes[i] for i in range(20)) / 20.0

            bar_time = bar.EndTime.time()
            eligible_time = time(9, 45) <= bar_time <= time(14, 30)

            if (eligible_time and previous_fast <= previous_slow
                    and current_fast > current_slow):
                self.pending_crossover_bar_end = bar.EndTime
        else:
            self.closes.Add(float(bar.Close))

    def OnData(self, data):
        self.HandleUnexpectedSpyPosition()
        self.HandleExpirationProcessing()

        if self.held_symbol is not None:
            if not self.Portfolio[self.held_symbol].Invested and self.exit_order_id is None:
                self.ClearHeldPosition()
            else:
                self.HandleTimeStop()
                self.HandleProfitTarget(data)

        if self.pending_crossover_bar_end is not None:
            signal_bar_end = self.pending_crossover_bar_end
            self.pending_crossover_bar_end = None
            self.TryEnter(data, signal_bar_end)

    def TryEnter(self, data, signal_bar_end):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            return

        if self.entry_order_id is not None:
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{signal_bar_end}: entry skipped; no option chain.")
            return

        today = self.Time.date()

        # Nearest listed expiration strictly after today (minimum calendar DTE).
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if (contract.Expiry.date() - today).days > 0
        })

        if not expirations:
            self.Debug(f"{signal_bar_end}: entry skipped; no valid expiration.")
            return

        expiration = expirations[0]
        spot = float(self.Securities[self.spy].Price)
        minimum_strike = spot * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == expiration
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{signal_bar_end}: entry skipped; no call at least 1% OTM "
                f"for {expiration}."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.held_expiry = selected.Expiry.date()

        self.Debug(
            f"{self.Time}: entry submitted: {selected.Symbol}, "
            f"expiry {self.held_expiry}, strike {selected.Strike}."
        )

    def HandleProfitTarget(self, data):
        if self.entry_price is None or self.exit_order_id is not None:
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        held_contract = next(
            (contract for contract in chain if contract.Symbol == self.held_symbol),
            None
        )
        if held_contract is None:
            return

        bid = float(held_contract.BidPrice)
        ask = float(held_contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.SubmitExit("profit target reached")

    def HandleTimeStop(self):
        if self.exit_order_id is not None or self.held_expiry is None:
            return

        if self.Time.time() != time(15, 45):
            return

        exchange_hours = self.Securities[self.spy].Exchange.Hours
        expiry_datetime = datetime.combine(self.held_expiry, time.min)
        prior_trading_day = exchange_hours.GetPreviousTradingDay(expiry_datetime).date()

        if self.Time.date() == prior_trading_day:
            self.SubmitExit("15:45 day-before-expiration stop")

    def HandleExpirationProcessing(self):
        if self.held_symbol is None or self.held_expiry is None:
            return

        if self.Time.date() >= self.held_expiry:
            self.no_entry_date = self.Time.date()
            if self.Portfolio[self.held_symbol].Invested:
                self.SubmitExit("expiration processing")
            else:
                self.ClearHeldPosition()

    def HandleUnexpectedSpyPosition(self):
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity == 0:
            return

        open_orders = self.Transactions.GetOpenOrders(self.spy)
        if not open_orders:
            self.Debug(
                f"{self.Time}: unexpected SPY position from exercise/assignment; "
                "liquidating."
            )
            self.MarketOrder(self.spy, -spy_quantity)

    def SubmitExit(self, reason):
        if self.held_symbol is None or self.exit_order_id is not None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            if order.Quantity < 0:
                self.Transactions.CancelOrder(order.Id)

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            self.ClearHeldPosition()
            return

        ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"{self.Time}: exit submitted for {self.held_symbol}; {reason}.")

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.entry_order_id = None
                self.Debug(
                    f"{self.Time}: entry filled: {self.held_symbol} "
                    f"at {self.entry_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None
                self.held_expiry = None
                self.Debug(f"{self.Time}: entry order canceled or invalid.")

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: exit filled: {order_event.Symbol} "
                    f"at {order_event.FillPrice:.2f}."
                )
                self.exit_order_id = None
                self.ClearHeldPosition()
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

    def ClearHeldPosition(self):
        self.held_symbol = None
        self.held_expiry = None
        self.entry_price = None
