from AlgorithmImports import *
from datetime import timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_five_minute_bar = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

        self.held_contract = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.expiration_liquidation_date = None

    def OnFiveMinuteBar(self, sender, bar):
        # OnData processes this using the same Slice that completed the bar.
        self.pending_five_minute_bar = bar

    def OnData(self, slice):
        self._liquidate_unexpected_spy_position()

        if self.held_contract is not None:
            expiration = self.held_contract.ID.Date.date()

            # Never intentionally carry an option into its expiration date.
            if self.Time.date() >= expiration:
                self.expiration_liquidation_date = self.Time.date()
                self._request_exit("expiration processing")
            else:
                self._check_profit_target(slice)
                self._check_time_stop(expiration)

        if self.pending_five_minute_bar is not None:
            bar = self.pending_five_minute_bar
            self.pending_five_minute_bar = None
            self._process_five_minute_bar(bar, slice)

    def _process_five_minute_bar(self, bar, slice):
        prior_fast = self.fast.Current.Value if self.fast.IsReady else None
        prior_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if self.fast.IsReady and self.slow.IsReady:
            crossed_up = (
                prior_fast is not None
                and prior_slow is not None
                and prior_fast <= prior_slow
                and self.fast.Current.Value > self.slow.Current.Value
            )

            self.previous_fast = self.fast.Current.Value
            self.previous_slow = self.slow.Current.Value

            bar_time = bar.EndTime.time()
            eligible_time = time(9, 45) <= bar_time <= time(14, 30)

            if crossed_up and eligible_time:
                self._try_enter(slice, bar.Close)

    def _try_enter(self, slice, spy_price):
        if self.held_contract is not None or self._ticket_open(self.entry_ticket):
            return

        if self.expiration_liquidation_date == self.Time.date():
            return

        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no SPY option chain.")
            return

        contracts = [
            contract
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.ID.Date.date() > self.Time.date()
        ]

        if not contracts:
            self.Debug("Skipped entry: no future-dated calls.")
            return

        # The requested expiration rule is interpreted as the nearest future
        # calendar expiration, preventing intentional expiration-day holdings.
        selected_expiration = min(contract.ID.Date.date() for contract in contracts)
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in contracts
            if contract.ID.Date.date() == selected_expiration
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(candidates, key=lambda c: (float(c.Strike), str(c.Symbol)))
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1, tag="Bullish MA call entry")
        self.Debug(
            f"Entry submitted: {selected.Symbol} strike {selected.Strike:.2f}, "
            f"expiry {selected.ID.Date.date()}."
        )

    def _check_profit_target(self, slice):
        if self.entry_price is None or self.entry_price <= 0:
            return

        contract = self._find_held_contract(slice)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._request_exit("50% profit target")

    def _check_time_stop(self, expiration):
        if self.Time.time() != time(15, 45):
            return

        previous_trading_day = self.Securities[self.spy].Exchange.Hours.GetPreviousTradingDay(
            expiration
        ).date()

        if self.Time.date() == previous_trading_day:
            self._request_exit("15:45 pre-expiration time stop")

    def _find_held_contract(self, slice):
        if self.held_contract is None:
            return None

        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == self.held_contract:
                    return contract

        return None

    def _request_exit(self, reason):
        if self.held_contract is None or self._ticket_open(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(order.Id)

        self.exit_ticket = self.MarketOrder(
            self.held_contract,
            -quantity,
            tag=f"Option exit: {reason}"
        )
        self.Debug(f"Exit submitted: {self.held_contract}; {reason}.")

    def _liquidate_unexpected_spy_position(self):
        if not self.Portfolio[self.spy].Invested:
            return

        if len(self.Transactions.GetOpenOrders(self.spy)) == 0:
            self.Debug("Unexpected SPY exercise/assignment position; liquidating.")
            self.Liquidate(self.spy, "Unexpected exercise or assignment")

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.entry_ticket = None
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}.")
                self.held_contract = None
                self.entry_price = None
                self.exit_ticket = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_ticket = None

    def _ticket_open(self, ticket):
        return (
            ticket is not None
            and ticket.Status not in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]
        )
