            period_end - timedelta(minutes=offset)
            for offset in range(5)
        }

        # Missing minute data means this five-minute bar is ignored entirely.
        if set(self._five_minute_bars.keys()) != expected_ends:
            return

        self._on_completed_five_minute_bar(period_end, minute_bar.Close, data)

