        ticket = self.MarketOrder(option_symbol, -quantity)
        self.exit_order_id = ticket.OrderId

        self.Debug(f"{self.Time}: Exit submitted for {option_symbol}: {reason}.")

    def _held_option_symbol(self):
        if self.held_option is None:
            return None

        if self.Portfolio[self.held_option].Quantity == 0:
            return None

        return self.held_option

    def _entry_order_open(self):
        if self.entry_order_id is None:
            return False

        order = self.Transactions.GetOrderById(self.entry_order_id)
        return order is not None and order.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted,
            OrderStatus.CancelPending
        ]

    def _exit_order_open(self):
        if self.exit_order_id is None:
