from AlgorithmImports import *
from datetime import datetime, timedelta, time as clock_time


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self._spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self._spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        self._option_symbol = self.AddOption("SPY", Resolution.Minute).Symbol
        self.Securities[self._option_symbol].SetDataNormalizationMode(
            DataNormalizationMode.Raw
        )
        self.SetOptionFilter()

        self._five_minute = TradeBarConsolidator(timedelta(minutes=5))
        self._five_minute.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(self._spy, self._five_minute)

        self._closes = RollingWindow[float](20)
        self._previous_fast = None
        self._previous_slow = None
        self._pending_entry_check = False

        self._held_contract = None
        self._held_expiry = None
        self._entry_price = None

        self._entry_ticket = None
        self._exit_ticket = None
        self._spy_liquidation_ticket = None
        self._block_entries_on = None

    def SetOptionFilter(self):
        # Broad strike and expiry coverage, including weekly SPY options.
        self.SetUniverseSelection(
            None
        )

    def OnSecuritiesChanged(self, changes):
        pass

    def InitializeOptionFilter(self):
        pass

    def OnData(self, data: Slice):
        self._handle_unexpected_spy_position()

        if self._held_contract is not None:
            self._handle_expiration_processing()
            self._handle_time_stop()
            self._handle_profit_target(data)

        if self._pending_entry_check:
            self._pending_entry_check = False
            self._try_enter(data)

    def SetWarmUp(self):
        pass

    def _on_five_minute_bar(self, sender, bar: TradeBar):
        # SPY's regular-session minute stream starts at 09:30, so this
        # time-based consolidator produces the first bar ending at 09:35.
        self._closes.Add(float(bar.Close))

        if not self._closes.IsReady:
            return

        fast = sum(self._closes[i] for i in range(5)) / 5.0
        slow = sum(self._closes[i] for i in range(20)) / 20.0

        bullish_cross = (
            self._previous_fast is not None
            and self._previous_fast <= self._previous_slow
            and fast > slow
        )

        self._previous_fast = fast
        self._previous_slow = slow

        bar_end = bar.EndTime.time()
        eligible_time = (
            clock_time(9, 45) <= bar_end <= clock_time(14, 30)
        )

        if bullish_cross and eligible_time:
            self._pending_entry_check = True

    def _try_enter(self, data: Slice):
        if self._block_entries_on == self.Time.date():
            return

        if self._held_contract is not None or self._entry_order_is_open():
            return

        chain = data.OptionChains.get(self._option_symbol)
        if chain is None:
            self.Debug("Entry skipped: no SPY option chain in current Slice.")
            return

        spy_price = float(self.Securities[self._spy].Price)
        if spy_price <= 0:
            self.Debug("Entry skipped: SPY price unavailable.")
            return

        today = self.Time.date()

        # No target DTE was specified, so use the nearest expiration strictly
        # after the current calendar date; this avoids intentional expiry-day holds.
        expirations = sorted(
            {
                contract.Expiry.date()
                for contract in chain.Contracts.Values
                if contract.Right == OptionRight.Call
                and contract.Expiry.date() > today
            }
        )

        if not expirations:
            self.Debug("Entry skipped: no future call expiration available.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in chain.Contracts.Values
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"Entry skipped: no eligible call for expiration {selected_expiry}."
            )
            return

        contract = sorted(
            candidates,
            key=lambda c: (float(c.Strike), str(c.Symbol))
        )[0]

        self._entry_ticket = self.MarketOrder(contract.Symbol, 1)
        self.Debug(
            f"Entry submitted: {contract.Symbol}, expiry {selected_expiry}, "
            f"strike {contract.Strike}."
        )

    def _handle_profit_target(self, data: Slice):
        if self._exit_order_is_open() or self._entry_price is None:
            return

        quote = data.QuoteBars.get(self._held_contract)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self._entry_price:
            self._submit_exit("profit target")

    def _handle_time_stop(self):
        if self._exit_order_is_open() or self._held_expiry is None:
            return

        if (
            self.Time.time() == clock_time(15, 45)
            and self._previous_trading_day(self._held_expiry) == self.Time.date()
        ):
            self._submit_exit("15:45 pre-expiration time stop")

    def _handle_expiration_processing(self):
        if self._held_expiry is None:
            return

        if self.Time.date() >= self._held_expiry:
            self._block_entries_on = self.Time.date()
            if not self._exit_order_is_open():
                self.Debug(
                    f"Expiration processing: liquidating {self._held_contract}."
                )
                self._submit_exit("expiration processing")

    def _previous_trading_day(self, expiry_date):
        exchange_hours = self.Securities[self._spy].Exchange.Hours
        expiry_midnight = datetime.combine(expiry_date, clock_time.min)
        return exchange_hours.GetPreviousMarketOpen(
            expiry_midnight, False
        ).date()

    def _submit_exit(self, reason: str):
        if self._held_contract is None or self._exit_order_is_open():
            return

        quantity = self.Portfolio[self._held_contract].Quantity
        if quantity == 0:
            return

        self._exit_ticket = self.MarketOrder(self._held_contract, -quantity)
        self.Debug(f"Exit submitted ({reason}): {self._held_contract}.")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self._spy].Quantity
        if quantity == 0:
            return

        if (
            self._spy_liquidation_ticket is None
            or not self._order_is_open(self._spy_liquidation_ticket)
        ):
            self.Debug(
                "Unexpected SPY position from exercise/assignment; liquidating."
            )
            self._spy_liquidation_ticket = self.MarketOrder(self._spy, -quantity)

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self._entry_ticket is not None
            and order_event.OrderId == self._entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self._held_contract = order_event.Symbol
                self._held_expiry = order_event.Symbol.ID.Date.date()
                self._entry_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entry filled: {order_event.Symbol} at "
                    f"{self._entry_price:.2f}."
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"Entry order closed without fill: {order_event.Symbol}.")

        if (
            self._exit_ticket is not None
            and order_event.OrderId == self._exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at "
                    f"{float(order_event.FillPrice):.2f}."
                )
                self._held_contract = None
                self._held_expiry = None
                self._entry_price = None
                self._exit_ticket = None

        if (
            self._spy_liquidation_ticket is not None
            and order_event.OrderId == self._spy_liquidation_ticket.OrderId
            and order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            )
        ):
            self._spy_liquidation_ticket = None

    def _entry_order_is_open(self):
        return self._entry_ticket is not None and self._order_is_open(
            self._entry_ticket
        )

    def _exit_order_is_open(self):
        return self._exit_ticket is not None and self._order_is_open(
            self._exit_ticket
        )

    @staticmethod
    def _order_is_open(ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )
